import fs from 'node:fs';
const pages=await(await fetch('http://127.0.0.1:9340/json/list')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let id=0;const calls=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const r=calls.get(m.id);calls.delete(m.id);r?.(m.result)}};const rpc=(method,params={})=>new Promise(r=>{const n=++id;calls.set(n,r);ws.send(JSON.stringify({id:n,method,params}))});const result=await rpc('Runtime.evaluate',{expression:'({url:location.href,active:workbench.state.tasks.filter(t=>["running","starting","waiting","queued","stopping"].includes(t.state)).length})',returnByValue:true});if(result.result.value.url.startsWith('http://127.0.0.1:7813/')&&result.result.value.active===0){ws.send(JSON.stringify({id:++id,method:'Runtime.evaluate',params:{expression:'window.close()'}}));console.log('Closed completed isolated QA window only');}ws.close();
